const PI:f64=3.14159265358979323846264338327950288;
const INVALID:f64=-1.0e300;
#[no_mangle]
pub extern "C" fn lamberts_ellipsoidal_distance(v:*const i64,n:usize)->f64{if n!=4||v.is_null(){return INVALID;}let a=unsafe{std::slice::from_raw_parts(v,n)};if a[0]<-90000000||a[0]>90000000||a[2]<-90000000||a[2]>90000000||a[1]<-180000000||a[1]>180000000||a[3]<-180000000||a[3]>180000000{return INVALID;}if a[0]==a[2]&&a[1]==a[3]{return INVALID;}let(lat1,lon1,lat2,lon2)=(a[0]as f64/1e6,a[1]as f64/1e6,a[2]as f64/1e6,a[3]as f64/1e6);let(p1,p2,l1,l2)=(lat1*PI/180.,lat2*PI/180.,lon1*PI/180.,lon2*PI/180.);let h=(((p2-p1)/2.).sin().powi(2)+p1.cos()*p2.cos()*((l2-l1)/2.).sin().powi(2)).sqrt();if h==0.{return INVALID;}let sigma=2.*h.asin();let f=(6378137.-6356752.314245)/6378137.;let b1=((1.-f)*(lat1*PI/180.).tan()).atan();let b2=((1.-f)*(lat2*PI/180.).tan()).atan();let p=(b1+b2)/2.;let q=(b2-b1)/2.;let x=(sigma-sigma.sin())*((p.sin().powi(2)*q.cos().powi(2))/(sigma/2.).cos().powi(2));let y=(sigma+sigma.sin())*((p.cos().powi(2)*q.sin().powi(2))/(sigma/2.).sin().powi(2));6378137.*(sigma-(f/2.)*(x+y))}
